"use client";
import { useState } from "react";
import { navigation } from "../../data/portfolio";
export function Navigation({ onNavigateAbout }: { onNavigateAbout?: () => void }) {
  const [open, setOpen] = useState(false);
  return <header className="site-header"><a className="wordmark" href="#home" aria-label="Karthikeya home">KARTHIKEYA<span>.DEV</span></a>
    <button className="menu-toggle" aria-expanded={open} aria-controls="primary-nav" onClick={() => setOpen(!open)}><span/>{open ? "CLOSE" : "MENU"}</button>
    <nav id="primary-nav" className={open ? "nav-links is-open" : "nav-links"} aria-label="Primary navigation">{navigation.map((item) => <a key={item} href={item === "01_HOME" ? "#home" : item === "02_ABOUT" ? "#about" : "#"} onClick={(event) => { setOpen(false); if (item === "02_ABOUT" && onNavigateAbout) { event.preventDefault(); onNavigateAbout(); } }}>{item}</a>)}<a className="nav-resume" href="#resume" data-cursor="hand">RESUME <span aria-hidden="true">↗</span></a></nav>
  </header>;
}
